`timescale 1ns / 1ps

module top_fsm_system (
    input  wire        clk,
    input  wire        rst,
    input  wire [12:0] writeData_in,
    input  wire [2:0]  state,
    output wire [15:0] leds_hw,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    // Internal signals generated by the state lookup (RTL_ROMs)
    reg  [9:0]  addr_rom_out;
    reg         readEn_rom_out;
    reg         writeEn_rom_out;

    // Interconnect wires for DUT (addressDecoder)
    wire [31:0] address;
    wire [31:0] writeData;
    wire [31:0] readData;
    wire [15:0] switches_in;

    // Constant & Zero-Extension Assignments (matching schematic)
    assign address     = {22'b0, addr_rom_out};       // Zero-extended from [9:0] to [31:0]
    assign writeData   = {19'b0, writeData_in};       // Zero-extended from [12:0] to [31:0]
    assign switches_in = 16'b1010010110100101;        // Hardcoded constant V=B"1010010110100101" (0xA5A5)

    // State Decoder (Synthesizes into addr_reg_i, readEn_reg_i, writeEn_reg_i RTL_ROMs)
    always @(*) begin
        case (state)
            3'b000: begin addr_rom_out = 10'h000; readEn_rom_out = 1'b0; writeEn_rom_out = 1'b0; end
            3'b001: begin addr_rom_out = 10'h004; readEn_rom_out = 1'b0; writeEn_rom_out = 1'b1; end // Write DataMemory
            3'b010: begin addr_rom_out = 10'h004; readEn_rom_out = 1'b1; writeEn_rom_out = 1'b0; end // Read DataMemory
            3'b011: begin addr_rom_out = 10'h100; readEn_rom_out = 1'b0; writeEn_rom_out = 1'b1; end // Write LEDs
            3'b100: begin addr_rom_out = 10'h200; readEn_rom_out = 1'b1; writeEn_rom_out = 1'b0; end // Read Switches
            3'b101: begin addr_rom_out = 10'h008; readEn_rom_out = 1'b0; writeEn_rom_out = 1'b1; end
            3'b110: begin addr_rom_out = 10'h008; readEn_rom_out = 1'b1; writeEn_rom_out = 1'b0; end
            3'b111: begin addr_rom_out = 10'h3FF; readEn_rom_out = 1'b0; writeEn_rom_out = 1'b0; end
            default: begin addr_rom_out = 10'h000; readEn_rom_out = 1'b0; writeEn_rom_out = 1'b0; end
        endcase
    end

    // Instantiate DUT: addressDecoder
    addressDecoder DUT (
        .address     (address),
        .clk         (clk),
        .readEnable  (readEn_rom_out),
        .rst         (rst),
        .switches_in (switches_in),
        .writeData   (writeData),
        .writeEnable (writeEn_rom_out),
        .leds_out    (leds_hw),
        .readData    (readData)
    );

    // Instantiate Display: SevenSegController
    SevenSegController Display (
        .clk   (clk),
        .rst   (rst),
        .value (readData[15:0]), // Lower 16 bits of readData bus
        .an    (an),
        .seg   (seg)
    );
endmodule
